import React, { useContext, useEffect, useState } from 'react';
import SingleBoard from './SingleBoard';
import { DragDropContext } from 'react-beautiful-dnd';
import { SkillItem, useAllSkills } from '../../../hooks/useAllSkills';
import { TheAppContext } from '../../../provider/AppContext';

const initial = {
  todo: {
    name: 'To Do',
    list: [],
  },
  inprogress: {
    name: 'In Progress',
    list: [],
  },
  mastered: {
    name: 'Mastered',
    list: [],
  },
};
export interface SkillBoardItem extends SkillItem {
  activated?: boolean;
}
const Scrumboard = () => {
  const { skills } = useAllSkills();
  const { skillControl } = useContext(TheAppContext);
  const [skill_boards, set_skill_boards] = useState(initial);
  const [filteredSkills, setFilteredSkills] = useState<SkillItem[]>([]);

  useEffect(() => {
    if (skills && filteredSkills.length === 0) setFilteredSkills(skills);
  }, [skills]);

  // const toggle_skills = ({ DisplayName, activated }) => {
  //   const boards = { ...skill_boards };
  //   Object.keys(boards).map((sk) => {
  //     boards[sk].list.map((skill) => {
  //       if (
  //         skill.Category.toLowerCase().replace(/ /gi, '') ===
  //         DisplayName.toLowerCase().replace(/ /gi, '')
  //       ) {
  //         skill.activated = activated;
  //       }
  //     });
  //   });
  //   set_skill_boards(boards);
  // };

  // useEffect(() => {
  //   const skillsToShow = skillControl
  //     .filter((c) => c.activated)
  //     .flatMap((s) => s.slug);

  //   setFilteredSkills((prev) =>
  //     skills.filter((s) => skillsToShow.includes(s.attributes.SkillCategory))
  //   );
  // }, [skillControl]);

  useEffect(() => {
    // const skills = Skill_JSON;
    const boardSkills: SkillBoardItem[] = [...skills];
    const boards = { ...skill_boards };

    boardSkills.forEach((skill) => {
      console.log(skill.attributes.skill.Mastery);
      skill.activated = skillControl.find(
        (s) => s.slug === skill.attributes.SkillCategory,
      )?.activated;
    });

    boards.todo.list = boardSkills.filter(
      (sk) => sk.attributes.skill.Mastery === 'To_Do',
    );
    boards.mastered.list = boardSkills.filter(
      (sk) => sk.attributes.skill.Mastery === 'Mastered',
    );
    boards.inprogress.list = boardSkills.filter(
      (sk) => sk.attributes.skill.Mastery === 'In Progress',
    );
    console.log({ boards });
    set_skill_boards(boards);
  }, [skillControl]);

  const handleReorder = (e) => {
    const { destination, source, draggableId } = e;
    if (!source?.droppableId || !destination?.droppableId) {
      return;
    }
    console.log({ draggableId });

    //first update the individual skill
    let boards = { ...skill_boards };

    let updated = boards[source.droppableId].list.find(
      (sk) => sk.id === draggableId,
    );

    updated.Mastery = destination.droppableId;
    let old_list = [...boards[source.droppableId].list];
    let new_list = [...boards[destination.droppableId].list];
    const [removed] = old_list.splice(source.index, 1);
    new_list.splice(destination.index, 0, removed);
    // then update the board
    set_skill_boards((prev) => ({
      ...prev,
      [source.droppableId]: {
        ...prev[source.droppableId],
        list: old_list,
      },
      [destination.droppableId]: {
        ...prev[destination.droppableId],
        list: new_list,
      },
    }));
  };

  const addSkill = (skill) => {
    let boards = { ...skill_boards };
    const name = skill.Mastery.toLowerCase().replace(/ /gi, '');

    boards[name].list.push(skill);

    const list_with_new = boards[name].list;

    set_skill_boards((prev) => ({
      ...prev,
      [name]: {
        ...prev[name],
        list: list_with_new,
      },
    }));
  };
  return (
    <section className="bg--3 padding-bot scrumboard" id={'skills'}>
      <div className="skill-scrum">
        <DragDropContext onDragEnd={handleReorder}>
          {skill_boards &&
            Object.keys(skill_boards).map((sk, index) => (
              <SingleBoard
                board_num={index + 1}
                skill_title={skill_boards[sk].name}
                list={skill_boards[sk].list}
                key={`${sk}--${index}`}
                addSkill={addSkill}
              />
            ))}
        </DragDropContext>
      </div>
    </section>
  );
};

export default Scrumboard;
