import React from 'react';
import styled from '@emotion/styled';
import { Box, Button, css, Typography } from '@mui/material';
import { graphql, Link, useStaticQuery } from 'gatsby';
import { GatsbyImage, getImage } from 'gatsby-plugin-image';
import { Download, Email } from '@mui/icons-material';
import { hover } from 'styles/animations';

const Styled__Box = styled(Box)(
  ({ theme }) => css`
    background-color: white;
    color: var(--as-gray);
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: ${theme.spacing(8)} 0;
  `,
);
const Styled__Inner = styled(Box)(({ theme }) => ({
  margin: 'auto',
  maxWidth: '650px',
  display: 'grid',
  gridTemplateColumns: '120px auto',
  gap: '3rem',
  alignItems: 'center',
  justifyContent: 'center',
  height: '100%',
  [theme.breakpoints.down('md')]: {
    '& .about-banner-image': {
      width: '250px',
      height: '250px',
      margin: 'auto',
    },
    paddingLeft: theme.spacing(2),
    paddingRight: theme.spacing(2),
    gridTemplateColumns: 'auto',
  },
}));

const Styled__Snippet = styled(Box)`
  position: relative;
`;
const AboutBanner = () => {
  const data = useStaticQuery(graphql`
    {
      a: strapiAbout {
        title
        resumeLink
        internal {
          owner
        }
        me {
          localFile {
            childImageSharp {
              gatsbyImageData(transformOptions: { grayscale: false })
            }
          }
        }
      }
    }
  `);

  return (
    <Styled__Box>
      <Styled__Inner>
        <Box className="about-banner-image">
          <GatsbyImage
            style={{ borderRadius: '100%' }}
            image={getImage(data.a.me.localFile)}
          />
        </Box>
        <Styled__Snippet>
          <Typography
            variant="body1"
            sx={{
              p: 2,
              fontSize: '1rem',
              textAlign: 'left',
              backgroundColor: 'var(--as-purple)',
              color: 'white',
              borderRadius: '12px',
              fontFamily: 'var(--as-font-family)',
              animation: `${hover} 3s ease-in-out infinite`,
            }}
          >
            Hi, I'm Al. I am a software developer and creative coder. I have
            spent the majority of my career working to use technology creatively
            to solve problems.
          </Typography>

          <Box
            sx={{
              pt: 2,
              display: 'flex',
              justifyContent: 'flex-end',
              alignItems: 'space-between',
              gap: 4,
            }}
          >
            <Link
              to="/resume"
              target="_blank"
              style={{ textDecoration: 'none' }}
            >
              <Button startIcon={<Download color="primary" />}>
                Download My Resume
              </Button>
            </Link>
            <Button
              href="mailto:alsigman@gmail.com"
              sx={{ color: 'info.main' }}
              startIcon={<Email color="info" />}
            >
              Contact
            </Button>
          </Box>
        </Styled__Snippet>
      </Styled__Inner>
    </Styled__Box>
  );
};

export default AboutBanner;
