import { styled } from '@mui/material/styles';
import { SwapVertRounded } from '@mui/icons-material';
import { Box, Switch, IconButton } from '@mui/material';
import React, { useContext, useEffect, useRef } from 'react';
import { TheAppContext } from '../../provider/AppContext';
import SingleSkillLegend from '../Codes/Scrumboard/SingleSkillLegend';

const MySwitch = styled(Switch)`
  && .MuiSwitch-track {
    background-color: var(--as-light-grey);
  }
`;
const Styled__Wrap = styled(Box)`
  background-color: white;
  ${({ theme }) => theme.breakpoints.down('md')} {
    width: 96%;
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    row-gap: 1rem;
    px: 2;
    border-radius: 12px;
  }
  &&.is-pinned {
    top: 0;
    border-radius: 0px;
    box-shadow: 0px 0px -5px 0px black;
    padding: 1rem 0;
    width: 100%;
    max-width: none;
  }
`;

const SkillFilters = () => {
  const { skillSortAsc, setSkillSortAsc, skillControl, handleSkillChange } =
    useContext(TheAppContext);

  const [isPinned, setIsPinned] = React.useState(false);
  const wrapRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([e]) => {
        setIsPinned(e.intersectionRatio < 1);
      },
      { threshold: [1], rootMargin: '-1px 0px 0px 0px' },
    );
    if (wrapRef.current) {
      observer.observe(wrapRef.current);
    }
    return () => {
      if (wrapRef.current) {
        observer.unobserve(wrapRef.current);
      }
    };
  }, []);

  return (
    <Styled__Wrap
      ref={wrapRef}
      data-testid="skill-filters"
      className={isPinned ? 'is-pinned' : ''}
      sx={{
        display: 'flex',
        mx: 'auto',
        width: '600px',
        py: 2,
        px: 5,
        mb: 5,
        borderRadius: '80px',
        alignItems: 'center',
        justifyContent: 'center',
        boxShadow: '0px 0px 16px -10px black',
        position: 'sticky',
        top: 0,
        zIndex: 1000,
        transition: 'all 0.3s ease',
      }}
    >
      {/* <Typography variant="h5">Filter</Typography> */}
      {/* FILTER BUTTON */}
      {/* <Box>
        <IconButton
          sx={{
            mr: 1,
            width: 50,
            color: 'white',
            backgroundColor: 'var(--as-purple)',
            transition: 'all 0.2s ease-in-out',
            '&:hover': {
              backgroundColor: 'var(--as-blue)',
            },
          }}
        >
          <FilterList />
        </IconButton>
      </Box> */}
      <Box
        sx={(theme) => ({
          [theme.breakpoints.down('md')]: {
            display: 'none',
          },
        })}
      >
        <IconButton
          data-testid="skill-sort-btn"
          sx={{
            mr: 2,
            width: 50,
            color: 'white',
            backgroundColor: 'var(--as-purple)',
            transition: 'all 0.2s ease-in-out',
            '&:hover': {
              backgroundColor: 'var(--as-blue)',
            },
          }}
          onClick={() =>
            setSkillSortAsc(skillSortAsc === 'asc' ? 'desc' : 'asc')
          }
        >
          <SwapVertRounded
            sx={{
              transform:
                skillSortAsc === 'asc' ? 'rotate(0deg)' : 'rotate(180deg)',
              transition: 'transform 0.2s ease-in-out',
            }}
          />
        </IconButton>
      </Box>
      {skillControl.map((sk, index) => (
        <SingleSkillLegend
          key={`legend--${index}`}
          activated={sk.activated}
          DisplayName={sk.DisplayName}
          toggle_square={() => handleSkillChange(sk.slug, sk.activated)}
          index={index}
        />
      ))}
    </Styled__Wrap>
  );
};

export default SkillFilters;
