import React, { useEffect, useRef, useContext, Suspense } from 'react';
import { TheAppContext } from '../../provider/AppContext';
import { useState } from 'react';
import { Box, Typography } from '@mui/material';
import styled from '@emotion/styled';
import { Typewriter } from 'react-simple-typewriter';
const HeaderSketch = React.lazy(() => import('./HeaderSketch'));

const StyledWrap = styled(Box)(({ theme }) => ({
  width: '100%',
  height: '50vh',
  minHeight: '100%',
  backgroundColor: 'black',
  position: 'relative',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  overflow: 'hidden',
  color: 'white',
  '& .header-text': {
    position: 'absolute',
    top: '25px',
    left: '5%',
    minWidth: '500px',
  },
  '& a, & h2, & h4': {
    color: 'white',
    textDecoration: 'none',
    fontWeight: 200,
    textAlign: 'left',
  },
  [theme.breakpoints.down('md')]: {
    '& .header-text': {
      // left: 0,
      // right: 0,
      // margin: 'auto',
      // minWidth: 'auto',
    },
  },
}));

const StyledHeader = styled(Box)(({ theme }) => ({
  position: 'absolute',
  top: 0,
  left: 0,
  height: '100%',
  width: '100%',
  maxHeight: '100vh',
}));

const Header = () => {
  const [sketch, setSketch] = useState(false);
  const { load_callback, menuOpen, boxShowing, setMenuOpen } =
    useContext(TheAppContext);

  let headerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    load_callback();
  }, []);

  useEffect(() => {
    if (headerRef.current) {
      if (menuOpen || boxShowing.visible) {
        setSketch(false);
      } else {
        setSketch(true);
      }
    }
    return () => setSketch(true);
  }, [menuOpen, boxShowing, headerRef]);

  return (
    <StyledWrap ref={headerRef} id={'home'}>
      <div className="header-text">
        <h2>
          <Typewriter
            words={["Hi, I'm Al."]}
            typeSpeed={100}
            loop={1}
            delaySpeed={1000}
          />
        </h2>

        <Typography
          sx={{ marginLeft: '2px', fontSize: '24px', fontWeight: 200 }}
          variant="body1"
          component={'div'}
        >
          I am a{' '}
          <span
            style={{ textDecoration: 'underline', color: 'var(--as-purple)' }}
          >
            <Typewriter
              words={[
                'software developer.',
                'creative coder.',
                'mentor.',
                'musician.',
                'technical ninja.',
                'designer.',
                'senior developer.',
              ]}
              loop={true}
              cursor
              cursorStyle="_"
              typeSpeed={30}
              deleteSpeed={10}
              delaySpeed={3000}
              cursorBlinking={true}
            />
          </span>
        </Typography>
      </div>
      {/* <header id="header"></header> */}
      {sketch ? (
        <StyledHeader>
          <Suspense
            fallback={
              <Box
                sx={{
                  bgcolor: 'black',
                  height: '50vh',
                  width: '100vw',
                }}
              ></Box>
            }
          >
            <HeaderSketch ref={headerRef} />
          </Suspense>
        </StyledHeader>
      ) : null}
    </StyledWrap>
  );
};

export default React.memo(Header);
